// Date de début des prochaines vacances (à minuit, heure locale)
const debutVacances = new Date("2026-11-07T00:00:00").getTime();

// On récupère l'élément de la page où afficher le compte à rebours
const compteur = document.getElementById("compteur");

// Ajoute un zéro devant les nombres à un chiffre : 7 devient "07"
function deuxChiffres(n) {
  return String(n).padStart(2, "0");
}

function mettreAJour() {
  // Temps restant en millisecondes entre maintenant et les vacances
  const reste = debutVacances - Date.now();

  // Si la date est passée, les vacances ont commencé : on s'arrête là
  if (reste <= 0) {
    compteur.textContent = "C'est maintenant ! 🎉";
    return;
  }

  // On découpe le temps restant en jours, heures, minutes et secondes.
  // Rappel : 1 s = 1 000 ms, 1 min = 60 000 ms,
  // 1 h = 3 600 000 ms et 1 jour = 86 400 000 ms.
  const jours    = Math.floor(reste / 86400000);
  const heures   = Math.floor((reste % 86400000) / 3600000);
  const minutes  = Math.floor((reste % 3600000) / 60000);
  const secondes = Math.floor((reste % 60000) / 1000);

  // On affiche le résultat dans la page
  compteur.textContent =
    jours + " j " +
    deuxChiffres(heures) + " h " +
    deuxChiffres(minutes) + " min " +
    deuxChiffres(secondes) + " s";

  // On relance la fonction dans 1 seconde pour faire défiler le compteur
  setTimeout(mettreAJour, 1000);
}

// Premier affichage immédiat, sans attendre une seconde
mettreAJour();
